tom:16px}.ok{background:#eaf7ee;border:1px solid #b9dfc2}.err{background:#fff0f0;border:1px solid #efc1c1}.info{background:#eef5ff;border:1px solid #c8dbf2}.health-panel{border-radius:16px;padding:17px;margin-bottom:18px;border:1px solid}.healthy-state{background:#edf8f0;border-color:#badfc4}.warning-state{background:#fff8e7;border-color:#ead395}.critical{background:#fff0f0;border-color:#e8b8b8}.health-title{font-weight:800}.health-chip{background:rgba(255,255,255,.72);border:1px solid rgba(76,95,82,.15)}.health-list{margin:12px 0 0;padding-left:20px;font-size:.87rem}.summary{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:11px;margin-bottom:18px}.stat,.card{background:var(--panel);border:1px solid var(--line);box-shadow:0 2px 12px rgba(22,40,29,.035)}.stat{border-radius:13px;padding:15px}.stat span,.meta span,.metric span{display:block;color:var(--muted);font-size:.76rem}.stat strong{display:block;font-size:1.35rem;margin-top:3px}.stat.attention strong{color:#9a3b28}.card{border-radius:15px;padding:17px}.section-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.75fr);gap:16px}.stack{display:grid;gap:16px}.system-card,.create-card{margin-bottom:18px}.system-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px;margin-top:14px}.metric,.meta div,.mini{background:var(--soft);border:1px solid #e4e9e5;border-radius:10px;padding:10px;min-width:0}.metric strong,.meta strong{display:block;margin-top:4px;word-break:break-word}.metric small,.meta small{display:block;color:#78827c;margin-top:3px;font-size:.71rem}.toolbar{margin:0 0 14px}.toolbar input,.toolbar select,input[type=text],input[type=datetime-local],select{border:1px solid #c9d3cc;background:#fff;border-radius:9px;padding:9px 10px;font:inherit}.toolbar input{min-width:250px;flex:1}.toolbar select{min-width:185px}.result-count{margin-left:auto;color:#6e7a72;font-size:.83rem}.grid{display:grid;gap:13px}.tenant-card.hidden{display:none}.tenant{font-size:1.06rem;font-weight:780}.technical{font-size:.76rem;color:#77827b;margin-top:3px}.badge{background:#edf1ee}.badge.active{background:#e8f6eb;color:#1f6a37}.badge.suspended{background:#fff4d8;color:#735b16}.badge.pending_delete,.badge.invalid,.chip.critical{background:#ffe6e6;color:#8a2b2b}.badge.setup_required,.badge.unmanaged,.chip.info{background:#eef0ff;color:#4d4b91}.chip.good{background:#e8f6eb;color:#1f6a37}.chip.warning{background:#fff4d8;color:#735b16}.meta{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px;margin:14px 0}.meta .bad strong{color:#9a322a}.btn{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;border:1px solid #bec9c1;background:#fff;color:#1d2b22;border-radius:9px;padding:8px 10px;font-weight:650;cursor:pointer;font:inherit;font-size:.88rem}.btn:hover{background:#f3f6f4}.btn:disabled{cursor:not-allowed;opacity:.46}.primary{background:var(--green);color:#fff;border-color:var(--green)}.danger{border-color:#d9a4a4;color:#8b2020}.warning{border-color:#d9c27e;color:#6c5511}.secondary{background:var(--soft)}.copy-ok{border-color:#9bc5a6;color:#21693a}.quicklinks{margin-left:auto}.details{margin-top:12px;border-top:1px solid #edf0ed;padding-top:11px}.details summary{cursor:pointer;color:#415148;font-weight:700;font-size:.86rem}.detail-body{padding-top:13px}.action-group{margin-top:14px;padding-top:12px;border-top:1px solid #edf0ed}.action-group h3{font-size:.84rem;margin-bottom:8px;color:#526158}.danger-zone{border:1px solid #edd0d0;background:#fffafa;border-radius:10px;padding:10px}.form-grid{display:grid;grid-template-columns:1.1fr 1fr 1.2fr;gap:11px}.field label,.modules-title{display:block;font-size:.8rem;font-weight:700;margin-bottom:5px}.field input,.field select{width:100%}.hint,.security-note{display:block;color:#748078;font-size:.75rem;margin-top:5px}.modules{margin-top:14px}.module-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.module-option{display:flex;gap:7px;align-items:center;background:var(--soft);border:1px solid #e2e7e3;border-radius:9px;padding:8px 9px;font-size:.83rem}.create-foot{align-items:center;margin-top:14px;padding-top:13px;border-top:1px solid #edf0ed}.setup-note,.warning-note,.invalid-note,.health-note{margin-top:10px;padding:9px 11px;border-radius:9px;font-size:.82rem}.setup-note{background:#f7f8ff;color:#4d4b72}.warning-note{background:#fff8e7;color:#6c5511}.invalid-note,.health-note{background:#fff0f0;color:#7c2929}.attention-list{margin:5px 0 0;padding-left:18px}.table-wrap{overflow-x:auto}.history-table{width:100%;border-collapse:collapse;margin-top:10px}.history-table th,.history-table td{text-align:left;padding:9px 8px;border-bottom:1px solid #edf0ed;font-size:.82rem;vertical-align:top}.history-table th{color:#6d7871;font-size:.72rem;text-transform:uppercase;letter-spacing:.04em}.result-ok{color:#21693a;font-weight:700}.result-failed,.stale{color:var(--red);font-weight:700}.empty,.no-results{background:#fff;border:1px dashed #cbd4ce;border-radius:13px;padding:22px;text-align:center;color:var(--muted)}.no-results[hidden]{display:none}.notification-list{display:grid;gap:8px;margin-top:12px}.notification{border-left:4px solid #c5cec8;background:#fafbfa;padding:10px 11px;border-radius:7px}.notification.critical{border-left-color:#b84444;background:#fff5f5}.notification.warning{border-left-color:#b58a16;background:#fffbef}.notification.info{border-left-color:#5578aa;background:#f4f8ff}.notification strong{display:block;font-size:.84rem}.notification span{font-size:.8rem;color:#58665e}.progress{height:8px;background:#e7ece8;border-radius:999px;overflow:hidden;margin:9px 0}.progress>span{display:block;height:100%;background:#2c8050}.step-list{display:grid;gap:7px;margin-top:12px}.step{display:flex;gap:9px;align-items:flex-start;font-size:.83rem}.step-dot{width:18px;height:18px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:#e6ebe7;color:#718078;font-size:.7rem;flex:0 0 18px}.step.done .step-dot{background:#dff1e4;color:#246b3c}.code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;background:#f1f4f2;border:1px solid #dfe5e0;border-radius:7px;padding:8px 9px;overflow-wrap:anywhere;font-size:.76rem}.operator-grid{display:grid;gap:10px;margin-top:12px}.operator-row{display:grid;grid-template-columns:minmax(150px,1fr) minmax(140px,.5fr) auto;gap:10px;align-items:center;border:1px solid #e2e8e3;border-radius:10px;padding:10px}.schedule-form{display:grid;grid-template-columns:1fr 1fr 1.2fr auto;gap:9px;align-items:end}.schedule-form label{font-size:.76rem;font-weight:700}.schedule-form select,.schedule-form input{width:100%;margin-top:4px}.section-title{margin-bottom:14px}.section-title p{margin:.35rem 0 0;color:var(--muted);font-size:.88rem}.foot{margin-top:22px;color:#77817b;font-size:.78rem}@media(max-width:1180px){.summary{grid-template-columns:repeat(3,minmax(0,1fr))}.section-grid{grid-template-columns:1fr}.system-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:1080px){.system-grid,.meta{grid-template-columns:repeat(3,minmax(0,1fr))}.shell{grid-template-columns:210px minmax(0,1fr)}}@media(max-width:820px){.shell{display:block}.sidebar{position:static;height:auto;padding:12px}.brand{padding:4px 8px 10px}.nav{display:flex;overflow-x:auto;gap:5px}.nav a{white-space:nowrap}.side-foot{position:static;border:0;padding:10px 8px 0}.wrap{padding:22px 16px 44px}.top{display:block}.top-actions{margin-top:12px}.form-grid,.schedule-form{grid-template-columns:1fr 1fr}.module-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.operator-row{grid-template-columns:1fr 1fr}.operator-row form{grid-column:1/-1}.quicklinks{margin-left:0}}@media(max-width:560px){.summary,.meta,.system-grid,.form-grid,.schedule-form,.module-grid{grid-template-columns:1fr}.toolbar input,.toolbar select{width:100%;min-width:0}.result-count{width:100%;margin-left:0}.card{padding:14px}}
